bruteForceSolution.code:
function findMinMax(nums) {
  nums.sort((a, b) => a - b);
  return [nums[0], nums[nums.length - 1]];
}

optimizedSolution.code:
function findMinMax(nums) {
  let min = nums[0];
  let max = nums[0];
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] < min) min = nums[i];
    if (nums[i] > max) max = nums[i];
  }
  return [min, max];
}
